#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2); // если не заработает, попробуйте 0x3F

const int TRIG_PIN = 4;
const int ECHO_PIN = 5;

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  digitalWrite(TRIG_PIN, LOW);

  Wire.begin(8, 9);          // SDA = 8, SCL = 9
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Distance:");
}

void loop() {
  // Импульс 10 мкс на TRIG
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  // Ждём эхо (timeout 30 мс ≈ 5 метров)
  long duration = pulseIn(ECHO_PIN, HIGH, 30000);

  if (duration == 0) {
    lcd.setCursor(0, 1);
    lcd.print("Out of range   ");
  } else {
    // Скорость звука ~343 м/с: расстояние = время * 0.0343 / 2
    float distance_cm = duration * 0.0343 / 2.0;

    lcd.setCursor(0, 1);
    lcd.print(distance_cm, 1); // одна цифра после запятой
    lcd.print(" cm       ");
  }

  delay(200);
}
